S transfer_message(const S& key, const S& fallback)
{
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_msgs)
        return ::cw::g_cwpy->m_setting->m_msgs->get(key, fallback);
    if (::cw::setting::Setting::s_msgs) return ::cw::setting::Setting::s_msgs->get(key, fallback);
    return fallback;
}

S format_transfer_message(S format, const std::vector<S>& values)
{
    // Python の % は、スキンのメッセージで使う一般的なスカ
    // ラー用プレースホルダーを受け付ける。 転送値は既に文字列化済み
    // なので、%s/%d/%i/%u/%f にも同じ文字列置換を使
    // える。 一度の走査で %% も処理し、翻訳済みメッセージに置
    // 換記号が残ったり、別の位置の値を消費したりしないようにする。
    std::size_t value_index=0;
    for (std::size_t position=0;position<format.size();) {
        if (format[position]!='%' || position+1>=format.size()) {
            ++position;
            continue;
        }
        if (format[position+1]=='%') {
            format.erase(position,1);
            ++position;
            continue;
        }
        const auto specifier=format[position+1];
        if (value_index<values.size() &&
            (specifier=='s' || specifier=='d' || specifier=='i' ||
             specifier=='u' || specifier=='f')) {
            format.replace(position,2,values[value_index++]);
            position+=values[value_index-1].size();
            continue;
        }
        ++position;
    }
    return format;
}

