S replace_root(const S& arg_path, const S& arg_from, const S& arg_to)
{
    if (arg_path.empty()) return {}; // 埋め込みカードには独立した XML ファイルがない。
    if (arg_from.empty() || arg_to.empty())
        throw std::invalid_argument("transfer requires source and destination roots");
    // OnOk は絶対ルートを保存するが、データベース・XML のヘッダ
    // ーは同じ作業ディレクトリーからの相対パスの場合がある。 同じ基準で
    // パスを比較し、黙って元の宿へ書き込む代替処理は行わない。 単体版・
    // ALL のデータルートやプロセスの作業ディレクトリーは変更しない。
    const auto path = fs::absolute(fs::u8path(arg_path)).lexically_normal();
    const auto from = fs::absolute(fs::u8path(arg_from)).lexically_normal();
    const auto relative = path.lexically_relative(from);
    if (relative.empty() || relative.has_root_path() ||
        std::any_of(relative.begin(), relative.end(), [](const auto& part) { return part == ".."; }))
        throw std::invalid_argument("transfer item is outside the source inn");
    return generic((fs::absolute(fs::u8path(arg_to)) / relative).lexically_normal());
}

