std::vector<S> xml_files(const fs::path& arg_dir)
{
    std::vector<S> result;
    std::error_code error;
    if (!fs::is_directory(arg_dir, error)) return result;
    for (const auto& entry : fs::directory_iterator(arg_dir, error)) {
        if (error || !entry.is_regular_file(error)) continue;
        auto extension = generic(entry.path().extension());
        std::transform(extension.begin(), extension.end(), extension.begin(),
                       [](unsigned char value) { return static_cast<char>(std::tolower(value)); });
        if (extension == ".xml") result.push_back(generic(entry.path()));
    }
    std::sort(result.begin(), result.end());
    return result;
}

void copy_tree(const fs::path& arg_source, const fs::path& arg_destination)
{
    std::error_code error;
    if (!fs::is_directory(arg_source, error)) throw std::runtime_error("transfer source directory is missing");
    fs::create_directories(arg_destination.parent_path(), error);
    if (error) throw std::runtime_error("cannot create transfer destination directory");
    fs::copy(arg_source, arg_destination, fs::copy_options::recursive, error);
    if (error) throw std::runtime_error("cannot copy transfer directory");
}

S skin_to_scenario(const S& arg_skindir)
{
    S result = "Scenario";
    if (arg_skindir.empty()) return result;
    const auto skin_file = fs::u8path("Data/Skin") / fs::u8path(arg_skindir) / "Skin.xml";
    std::error_code error;
    if (!fs::is_regular_file(skin_file, error)) return result;
    const auto skin = ::cw::data::xml2element(generic(skin_file), "", std::nullopt, std::nullopt, true, std::nullopt);
    if (!skin) return result;
    // Skin.xml は Property の下の要素テキストに種別を保存する。 ルート
    // や Property の属性を先に読むと古い値・空の値を選ぶ可能性があり、Python
    // の GetProperty(properties["Type"]) と異なる。
    const auto type = skin->gettext("Property/Type", "");
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
        for (const auto& [skin_type, folder] : ::cw::g_cwpy->m_setting->m_folderoftype) {
            if (skin_type == type && !folder.empty()) return folder;
        }
    }
    return result;
}

