void rewrite_image_path(const E& arg_element, const std::map<S, S>& arg_imgpaths)
{
    if (!arg_element) return;
    const auto found = arg_imgpaths.find(arg_element->m_text);
    if (found != arg_imgpaths.end()) arg_element->m_text = found->second;
}

void rewrite_scenario_log(const ET& arg_log, const std::map<S, S>& arg_imgpaths)
{
    if (!arg_log || !arg_log->getroot()) return;
    if (const auto music = arg_log->find("Property/MusicPath"); music && *music &&
        (*music)->getbool(".", ::cw::lib::Value("inusecard"), false)) {
        rewrite_image_path(*music, arg_imgpaths);
    }
    if (const auto musics = arg_log->find("Property/MusicPaths"); musics && *musics) {
        for (const auto& music : (*musics)->m_children) if (music &&
            music->getbool(".", ::cw::lib::Value("inusecard"), false)) {
            rewrite_image_path(music, arg_imgpaths);
        }
    }
    auto backgrounds = arg_log->find("BgImages");
    if (!backgrounds) backgrounds = arg_log->find("Property/BgImages");
    if (backgrounds && *backgrounds) for (const auto& background : (*backgrounds)->m_children) if (background) {
        const auto image = background->find("ImagePath");
        if (image && *image && (*image)->getbool(".", ::cw::lib::Value("inusecard"), false)) {
            rewrite_image_path(*image, arg_imgpaths);
        }
    }
}

void rewrite_face_log(const ET& arg_log, const std::map<S, S>& arg_imgpaths,
                      const std::map<S, S>& arg_membertable)
{
    if (!arg_log || !arg_log->getroot()) return;
    for (const auto& element : arg_log->getroot()->m_children) if (element) {
        const auto member = element->get("member", "");
        const auto found_member = arg_membertable.find(member);
        // Python と同様、名前変更がない場合も member 属性を書き込む。
        element->set("member", found_member == arg_membertable.end() ? member : found_member->second);
        if (element->m_tag == "ImagePath") {
            rewrite_image_path(element, arg_imgpaths);
        } else if (element->m_tag == "ImagePaths") {
            for (const auto& image : element->m_children) rewrite_image_path(image, arg_imgpaths);
        }
    }
}

enum class TransferItemKind {
    element,
    cash,
    album,
    partyrecord,
    party,
    adventurer,
    card,
    saved_jpdc_image,
    saved_variables,
    skin_variables,
};

TransferItemKind transfer_item_kind(const TransferItem& arg_item)
{
    return std::visit([](const auto& arg_value) -> TransferItemKind {
        using Type = std::decay_t<decltype(arg_value)>;
        if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::data::CWPyElement>>) {
            return TransferItemKind::element;
        } else if constexpr (std::is_same_v<Type, ::cw::lib::Integer>) {
            return TransferItemKind::cash;
        } else if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>>) {
            return TransferItemKind::album;
        } else if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>>>) {
            return TransferItemKind::partyrecord;
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::PartyHeader>>) {
            return TransferItemKind::party;
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::AdventurerHeader>>) {
            return TransferItemKind::adventurer;
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::CardHeader>>) {
            return TransferItemKind::card;
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::SavedJPDCImageHeader>>) {
            return TransferItemKind::saved_jpdc_image;
        } else if constexpr (std::is_same_v<Type, SavedVariableTransfer>) {
            return TransferItemKind::saved_variables;
        } else if constexpr (std::is_same_v<Type, SkinVariableTransfer>) {
            return TransferItemKind::skin_variables;
        } else {
            static_assert(std::is_same_v<Type, void>, "unhandled TransferItem alternative");
        }
    }, arg_item);
}

S transfer_item_label(const TransferItem& item)
{
    return std::visit([](const auto& value) -> S {
        using Type = std::decay_t<decltype(value)>;
        if constexpr (std::is_same_v<Type, E>) {
            if (!value) return "(不明)";
            if (value->m_tag == "Bookmarks") return transfer_message("bookmark", "ブックマーク");
            if (value->m_tag == "Gossips") return transfer_message("gossip", "ゴシップ");
            if (value->m_tag == "CompleteStamps")
                return transfer_message("complete_stamp", "終了印");
            return value->m_tag;
        } else if constexpr (std::is_same_v<Type, I>) {
            return format_transfer_message(transfer_message("currency", "%s sp"),
                                            {std::to_string(value)});
        } else if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>>) {
            return transfer_message("album", "アルバム");
        } else if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>>>) {
            return transfer_message("select_party_record", "編成記録");
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::PartyHeader>>) {
            return value ? value->m_name : S{};
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::AdventurerHeader>>) {
            return value ? value->m_name : S{};
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::CardHeader>>) {
            return value ? value->m_name : S{};
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::SavedJPDCImageHeader>>) {
            if (!value) return "JPDC";
            return value->m_scenarioauthor.empty()
                ? "JPDC - " + value->m_scenarioname
                : "JPDC - " + value->m_scenarioname + "(" + value->m_scenarioauthor + ")";
        } else if constexpr (std::is_same_v<Type, SavedVariableTransfer>) {
            const auto& key = std::get<0>(value);
            return std::get<1>(key).empty()
                ? "状態変数 - " + std::get<0>(key)
                : "状態変数 - " + std::get<0>(key) + "(" + std::get<1>(key) + ")";
        } else if constexpr (std::is_same_v<Type, SkinVariableTransfer>) {
            return std::get<4>(value).empty()
                ? "スキン「" + std::get<3>(value) + "」の状態変数"
                : "スキン「" + std::get<3>(value) + "(" + std::get<4>(value) + ")」の状態変数";
        }
        else return "転送データ";
    }, item);
}

S transfer_item_icon(const TransferItem& item)
{
    return std::visit([](const auto& value) -> S {
        using Type = std::decay_t<decltype(value)>;
        if constexpr (std::is_same_v<Type, E>) {
            if (!value) return {};
            if (value->m_tag == "Bookmarks") return "BOOKMARK";
            if (value->m_tag == "Gossips") return "EVT_GET_GOSSIP";
            if (value->m_tag == "CompleteStamps") return "EVT_GET_COMPLETESTAMP";
        } else if constexpr (std::is_same_v<Type, I>) {
            return "MONEY";
        } else if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>>) {
            return "CARD";
        } else if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>>>) {
            return "SELECTION";
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::PartyHeader>>) {
            return "MEMBER";
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::AdventurerHeader>>) {
            return "EVT_GET_CAST";
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::CardHeader>>) {
            if (value && value->m_type == "SkillCard") return "EVT_GET_SKILL";
            if (value && value->m_type == "ItemCard") return "EVT_GET_ITEM";
            if (value && value->m_type == "BeastCard") return "EVT_GET_BEAST";
        } else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::SavedJPDCImageHeader>>) {
            return "JPDCIMAGE";
        } else if constexpr (std::is_same_v<Type, SavedVariableTransfer> ||
                             std::is_same_v<Type, SkinVariableTransfer>) {
            return "VARIABLES";
        }
        return {};
    }, item);
}

I transfer_item_progress(const TransferItem& item)
{
    return std::visit([](const auto& value) -> I {
        using Type = std::decay_t<decltype(value)>;
        if constexpr (std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>> ||
                      std::is_same_v<Type, std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>>>)
            return std::max<I>(1, static_cast<I>(value.size()));
        else if constexpr (std::is_same_v<Type, std::shared_ptr<::cw::header::PartyHeader>>) {
            if (!value) return 1;
            I count = 2 + static_cast<I>(value->m_members.size());
            const auto directory = fs::u8path(value_string(value->m_fpath)).parent_path();
            std::error_code error;
            for (const auto& name : {S{"SkillCard"}, S{"ItemCard"}, S{"BeastCard"}}) {
                const auto path = directory / fs::u8path(name);
                if (!fs::is_directory(path, error)) continue;
                count += static_cast<I>(std::distance(fs::directory_iterator(path, error), fs::directory_iterator{}));
            }
            return std::max<I>(1, count);
        } else return 1;
    }, item);
}

