std::shared_ptr<TransferUiBackend> get_transfer_ui_backend()
{
    // モデル所有の Presentation
    // に転送手順全体を含め、UI の実装を
    // 一つに保つ。 OS はホストのサービ
    // スだけを提供し、別の配置は持たない。
    static const auto backend = std::make_shared<SharedTransferUiBackend>();
    return backend;
}

TransferYadoDataDialog::~TransferYadoDataDialog()
{
    if(m_thread) m_thread->m_cancel_requested.store(true,std::memory_order_release);
    release_transfer_slot();
    ::cw::dialog::clear_transient_dialog_presentation(this);
    if (m_ui_backend) m_ui_backend->unbind(reinterpret_cast<TransferUiBackend::Token>(this));
}

void TransferYadoDataDialog::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, std::vector<::cw::lib::String> arg_yadodirs, std::vector<::cw::lib::String> arg_yadonames, ::cw::lib::String arg_selected)
{
    dialog_retained_surface().reset();
    if(m_transfer_running) throw std::logic_error("cannot reuse a running transfer dialog");
    m_type_search.reset();
    release_transfer_slot();m_completion_handled=false;m_transfer_joined=false;m_thread.reset();
    m_parent = std::move(arg_parent);
    m_cwpy_debug = false;
    m_yadodirs = std::move(arg_yadodirs);
    m_yadonames = std::move(arg_yadonames);
    auto selected = std::find(m_yadodirs.begin(), m_yadodirs.end(), arg_selected);
    const auto destination = selected == m_yadodirs.end()
        ? ::cw::lib::Integer{0}
        : static_cast<::cw::lib::Integer>(std::distance(m_yadodirs.begin(), selected));
    m_to_index = destination;
    m_from_index = destination == 0 ? 1 : 0;
    if (m_from_index >= static_cast<I>(m_yadodirs.size())) m_from_index = 0;
    m_index = m_from_index;
    m_checked.clear();
    m_ok_enabled = false;
    m_cancelled = false;
    m_last_error.clear();
    visible = true;
    m_modal_result = 0;
    m_scroll_offset = 0;
    m_open_combo = -1;
    m_combo_cursor=0;m_combo_offset=0;m_horizontal_offset=0;
    m_row=-1;m_anchor=-1;m_selected.clear();m_focus=0;m_scroll_drag=-1;m_modifiers=0;
    m_ui_backend = get_transfer_ui_backend();
    bind_ui();
    _update_list();
    _do_layout();
}

void TransferYadoDataDialog::_update_list()
{
    m_data.clear();
    // PythonのDeleteAllItemsと同じく、読み込みが失敗しても旧チェック状態を残さない。
    m_checked.clear();
    m_selected.clear();m_row=-1;m_anchor=-1;m_scroll_offset=0;m_horizontal_offset=0;
    if (m_yadodirs.empty() || m_from_index < 0 || m_from_index >= static_cast<I>(m_yadodirs.size())) {
        m_checked.clear();
        _enable_btn();
        return;
    }
    m_index = m_from_index;
    const auto yado = fs::u8path(m_yadodirs[static_cast<std::size_t>(m_from_index)]);
    auto environment = ::cw::data::xml2etree(generic(yado / "Environment.xml"), "", std::nullopt, std::nullopt, true);
    if (!environment) throw std::runtime_error("transfer source Environment.xml is missing");
    const auto skin_path = yado / "SkinVariables.xml";
    if (fs::is_regular_file(skin_path)) {
        const auto skin_tree = ::cw::data::xml2etree(generic(skin_path), "", std::nullopt, std::nullopt, true);
        if (skin_tree && skin_tree->getroot()) {
            const auto variables = ::cw::data::YadoData::get_savedvariables_with_skin(skin_tree->getroot());
            const auto skin_keys = ::cw::data::get_skinkeys();
            std::vector<std::tuple<S, S, S>> keys;
            // Python と同様、登録済みのスキンのキー表を走査し、 SkinVariables.xml
            // 内の不明・古い変数は意図的に表示しない。
            for (const auto& [key, name_author] : std::get<1>(skin_keys)) {
                if (!variables.contains(key)) continue;
                keys.emplace_back(std::get<0>(name_author), std::get<1>(name_author), key);
            }
            std::sort(keys.begin(), keys.end(), logical_tuple_less<std::tuple<S, S, S>>);
            for (const auto& [name, author, key] : keys) {
                const auto& element = std::get<0>(variables.at(key));
                if (element) m_data.emplace_back(SkinVariableTransfer{key, element, true, name, author});
            }
        }
    }
    if (const auto bookmarks = environment->find("Bookmarks"); bookmarks && *bookmarks) m_data.emplace_back(*bookmarks);
    const auto cashbox = environment->getint("Property/Cashbox", std::nullopt, 0);
    if (cashbox != 0) m_data.emplace_back(cashbox);
    if (const auto gossips = environment->find("Gossips"); gossips && *gossips && !(*gossips)->m_children.empty()) m_data.emplace_back(*gossips);
    if (const auto stamps = environment->find("CompleteStamps"); stamps && *stamps && !(*stamps)->m_children.empty()) m_data.emplace_back(*stamps);

    auto yado_db = std::make_shared<::cw::yadodb::YadoDB>();
    yado_db->initialize(m_yadodirs[static_cast<std::size_t>(m_from_index)], ::cw::yadodb::g_YADO);
    auto album = yado_db->get_album();
    if (!album.empty()) m_data.emplace_back(std::move(album));
    auto party_records = yado_db->get_partyrecord();
    if (!party_records.empty()) m_data.emplace_back(std::move(party_records));
    const auto saved = ::cw::data::YadoData::get_savedvariables(environment);
    std::vector<std::tuple<S, S>> saved_keys;
    for (const auto& [key, unused] : saved) { (void)unused; saved_keys.emplace_back(std::get<0>(key), std::get<1>(key)); }
    std::sort(saved_keys.begin(), saved_keys.end(), logical_tuple_less<std::tuple<S, S>>);
    for (const auto& key : saved_keys) {
        const auto found = saved.find(key);
        if (found != saved.end() && std::get<0>(found->second)) m_data.emplace_back(SavedVariableTransfer{key, std::get<0>(found->second), false});
    }
    auto saved_jpdcimage = yado_db->get_savedjpdcimage();
    std::vector<std::tuple<S, S>> jpdc_keys;
    for (const auto& [key, unused] : saved_jpdcimage) {
        (void)unused;
        jpdc_keys.emplace_back(std::get<0>(key), std::get<1>(key));
    }
    std::sort(jpdc_keys.begin(), jpdc_keys.end(), logical_tuple_less<std::tuple<S, S>>);
    for (const auto& key : jpdc_keys) {
        const auto found = saved_jpdcimage.find(key);
        if (found != saved_jpdcimage.end() && found->second) m_data.emplace_back(found->second);
    }

    std::set<S> party_members;
    auto parties = yado_db->get_parties();
    for (const auto& header : parties) {
        if (!header) continue;
        for (const auto& member : header->m_members) if (const auto* name = std::get_if<S>(&member.storage())) party_members.insert(*name);
        m_data.emplace_back(header);
    }
    auto standbys = yado_db->get_standbys();
    for (const auto& header : standbys) if (header) {
        const auto path = value_string(header->m_fpath);
        if (party_members.contains(generic(fs::u8path(path).stem()))) continue;
        m_data.emplace_back(header);
    }
    auto cards = yado_db->get_cards();
    for (const auto& header : cards) if (header) {
        m_data.emplace_back(header);
    }
    yado_db->close();
    m_checked.assign(m_data.size(), false);
    _enable_btn();
}

void TransferYadoDataDialog::_enable_btn()
{
    m_ok_enabled = visible && !m_transfer_running && m_from_index != m_to_index &&
        std::any_of(m_checked.begin(), m_checked.end(), [](bool value) { return value; });
    sync_ui();
}

void TransferYadoDataDialog::OnFromYado(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(!visible || m_transfer_running) return;
    if(!arg_event || arg_event->id<0 || arg_event->id>=static_cast<I>(m_yadodirs.size()))return;
    transfer_play_sound("page");
    if(arg_event->id==m_from_index)return;
    m_from_index=arg_event->id;
    _update_list();
}

void TransferYadoDataDialog::OnToYado(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(!visible || m_transfer_running) return;
    if (arg_event && arg_event->id >= 0 && arg_event->id < static_cast<I>(m_yadodirs.size())) m_to_index = arg_event->id;
    _enable_btn();
}

void TransferYadoDataDialog::release_transfer_slot()
{
    if(m_owns_transfer_slot) {
        m_owns_transfer_slot=false;
        g_transfer_active.store(false,std::memory_order_release);
    }
}
void TransferYadoDataDialog::OnOk(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if(!visible || m_transfer_running) return;
    _enable_btn();
    if(!m_ok_enabled || !m_ui_backend) return;
    std::vector<TransferItem> sequence;
    for(std::size_t i=0;i<m_data.size() && i<m_checked.size();++i)
        if(m_checked[i]) sequence.push_back(m_data[i]);
    if(sequence.empty() || m_from_index<0 || m_to_index<0 ||
       m_from_index>=static_cast<I>(m_yadodirs.size()) || m_to_index>=static_cast<I>(m_yadodirs.size())) return;
    bool expected=false;
    if(!g_transfer_active.compare_exchange_strong(expected,true,std::memory_order_acq_rel)) return;
    m_owns_transfer_slot=true;m_transfer_running=true;m_completion_handled=false;m_transfer_joined=false;
    m_last_error.clear();m_open_combo=-1;
    struct Finish {
        TransferYadoDataDialog& owner;
        ~Finish(){owner.m_transfer_running=false;owner.release_transfer_slot();owner._enable_btn();}
    } finish{*this};
    try {
        // Python と同様、転送確認を尋ねる前に保留中のファイル書き込
        // みを待つ。 その後ユーザーがキャンセルする場合も同じ順序とする
        // 。ワーカーを直接呼ぶ場合に備え、ワーカー自身の同期も維持する。
        if (::cw::g_fsync) ::cw::g_fsync->sync();
        // 確認を尋ねる前に対象の識別情報を保持する。 入れ子のモーダルで確認済
        // みの転送先を変えたり、二つの別名を同じ宿へのコピーに変えたりしない。
        const auto root=fs::current_path();
        const auto from=fs::absolute(fs::u8path(m_yadodirs[m_from_index])).lexically_normal();
        const auto to=fs::absolute(fs::u8path(m_yadodirs[m_to_index])).lexically_normal();
        if(fs::equivalent(from,to)) throw std::runtime_error("同じ宿へは転送できません。");
        const S from_name=m_from_index<static_cast<I>(m_yadonames.size())?m_yadonames[m_from_index]:m_yadodirs[m_from_index];
        const S to_name=m_to_index<static_cast<I>(m_yadonames.size())?m_yadonames[m_to_index]:m_yadodirs[m_to_index];
        transfer_play_sound("signal");
        if(!m_ui_backend->confirm(transfer_message("message","メッセージ"),
            format_transfer_message(transfer_message("confirm_transfer","「%s」の%s件のデータを「%s」へ転送してよろしいですか？"),
                {from_name,std::to_string(sequence.size()),to_name}))) return;
        if(!visible || m_cancelled) return;
        if(fs::current_path()!=root) throw std::runtime_error("確認中に作業場所が変更されました。転送し直してください。");
        I maximum=0;
        for(const auto& item:sequence) maximum+=transfer_item_progress(item);
        m_thread=std::make_shared<_TransferThread>();
        m_thread->initialize(shared_from_this(),::cw::lib::encoding::path_to_utf8(from),
            ::cw::lib::encoding::path_to_utf8(to),std::move(sequence));
        auto progress=std::make_shared<::cw::dialog::progress::ProgressDialog>();
        progress->initialize(m_parent,transfer_message("transfer_data","データの転送"),{},std::max<I>(1,maximum),0,false,420);
        const auto thread=m_thread;
        if(!::cw::dialog::progress::run_modal_task(progress,[thread](const auto& update) {
            thread->m_progress_callback=update;
            struct Reset {std::shared_ptr<_TransferThread> thread;~Reset(){thread->m_progress_callback={};}} reset{thread};
            thread->run();
        })) {
            if(!visible || m_cancelled) return;
            throw std::runtime_error("転送の進捗画面を表示できませんでした。");
        }
        m_transfer_joined=true;
        complete_transfer();
    } catch(const std::exception& error) {
        m_last_error=error.what();
        if(visible && m_ui_backend) m_ui_backend->show_message("転送エラー",m_last_error,true);
    } catch(...) {
        m_last_error="不明な転送例外";
        if(visible && m_ui_backend) m_ui_backend->show_message("転送エラー",m_last_error,true);
    }
}

void TransferYadoDataDialog::complete_transfer()
{
    if(!m_thread || !m_transfer_joined || m_completion_handled) return;
    const auto state=m_thread->progress_snapshot();
    if(!state.finished) return;
    m_completion_handled=true;
    if(!visible || state.cancelled || m_cancelled || m_thread->m_cancel_requested.load(std::memory_order_acquire)) {
        m_modal_result=0;visible=false;return;
    }
    m_last_error=state.error;
    if(state.failed || !m_last_error.empty()) {
        if(m_last_error.empty()) m_last_error="データの転送に失敗しました。";
        if(m_ui_backend) m_ui_backend->show_message("転送エラー",m_last_error,true);
        return;
    }
    transfer_play_sound("harvest");
    if(m_ui_backend) m_ui_backend->show_message(transfer_message("message","メッセージ"),
        transfer_message("transfer_success","データの転送が完了しました。"),false);
    if(!visible || m_cancelled) return;
    m_modal_result=1;visible=false;
}

void TransferYadoDataDialog::transfer_bookmark(::cw::lib::String arg_fromscedir, ::cw::lib::String arg_toscedir, ::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::data::CWPyElement> arg_be, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    (void)arg_fromyado;
    (void)arg_toyado;
    if (!arg_counter || !arg_counter->m_environment) throw std::invalid_argument("transfer_bookmark requires a transfer counter and Environment.xml");
    if (!arg_be || arg_be->m_tag != "Bookmarks") throw std::invalid_argument("transfer_bookmark requires Bookmarks");
    auto bookmark = arg_counter->m_environment->find("Bookmarks");
    E target = bookmark && *bookmark ? *bookmark : ::cw::data::make_element("Bookmarks");
    if (!bookmark || !*bookmark) {
        const auto root = arg_counter->m_environment->getroot();
        if (!root) throw std::runtime_error("destination Environment.xml has no root");
        root->append(target);
    }
    const auto join_parts = [](const std::vector<S>& paths) {
        S joined;
        for (std::size_t i = 0; i < paths.size(); ++i) {
            if (i) joined += '/';
            joined += paths[i];
        }
        return joined;
    };
    std::set<std::pair<S, S>> exists;
    for (const auto& item : target->m_children) {
        if (!item) continue;
        std::vector<S> paths;
        for (const auto& path : item->m_children) if (path) paths.push_back(path->m_text);
        auto path = item->get("path", "");
        if (path.empty()) {
            path = ::cw::data::find_scefullpath(arg_toscedir, paths);
            item->set("path", path);
        }
        if (!path.empty()) path = ::cw::util::get_keypath(path);
        exists.emplace(join_parts(paths), path);
    }
    for (const auto& item : arg_be->m_children) {
        if (!item) continue;
        std::vector<S> paths;
        for (const auto& path : item->m_children) if (path) paths.push_back(path->m_text);
        auto path = item->get("path", "");
        if (path.empty()) {
            path = ::cw::data::find_scefullpath(arg_fromscedir, paths);
            item->set("path", path);
        }
        if (!path.empty()) path = ::cw::util::get_keypath(path);
        if (exists.emplace(join_parts(paths), path).second) target->append(item);
    }
    arg_counter->m_environment->m_is_edited = true;
    arg_counter->increment_progress();
}

void TransferYadoDataDialog::transfer_gossip(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::data::CWPyElement> arg_ge, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    transfer_elementlist(std::move(arg_fromyado), std::move(arg_toyado), std::move(arg_ge), std::move(arg_counter), "Gossips");
}

void TransferYadoDataDialog::transfer_completestamp(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::data::CWPyElement> arg_ce, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    transfer_elementlist(std::move(arg_fromyado), std::move(arg_toyado), std::move(arg_ce), std::move(arg_counter), "CompleteStamps");
}

void TransferYadoDataDialog::transfer_elementlist(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::data::CWPyElement> arg_ee, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter, ::cw::lib::String arg_tag)
{
    (void)arg_fromyado;
    (void)arg_toyado;
    if (!arg_counter) throw std::invalid_argument("transfer_elementlist requires a transfer counter");
    if (!arg_counter->m_environment) throw std::runtime_error("transfer_elementlist requires destination Environment.xml");
    if (!arg_ee) throw std::invalid_argument("transfer_elementlist requires source data");
    if (arg_tag.empty()) throw std::invalid_argument("transfer_elementlist requires a destination tag");

    // Python版のfind_exists()と同じく、Gossips/CompleteStampsが宛先に
    // 無い場合はXML構造不正として失敗させる。ファイル生成・Environment
    // のロードはworker側の依存処理で行う。
    const auto edata = arg_counter->m_environment->find_exists(arg_tag);
    std::set<::cw::lib::String> exists;
    for (const auto& element : edata->m_children) {
        if (element) exists.insert(element->m_text);
    }
    for (const auto& element : arg_ee->m_children) {
        if (element && exists.insert(element->m_text).second) edata->append(element);
    }
    arg_counter->m_environment->m_is_edited = true;
    arg_counter->increment_progress();
}

void TransferYadoDataDialog::rewrite_log_members(
    S directory, const std::map<S, S>& names, const std::function<void(ET)>& rewrite)
{
    if (directory.empty() || !rewrite)
        throw std::invalid_argument("scenario log member rewrite requires a directory and writer");
    const auto root = fs::absolute(fs::u8path(directory)).lexically_normal();
    struct Member { fs::path source, destination; ET data; };
    std::vector<Member> members;
    std::set<fs::path> destinations;
    // Python は Members を置き換える前に Members2 を用意する。 ここでも同等
    // の XML スナップショットを保持し、まだ読んでいないメンバーを出力先が上書きしないようにする。
    for (const auto& path : xml_files(root)) {
        const auto found = names.find(generic(fs::u8path(path).stem()));
        if (found == names.end())
            throw std::out_of_range("scenario log member was not transferred: " + path);
        const auto& name = found->second;
        const auto filename = fs::u8path(name + ".xml");
        if (name.empty() || name == "." || name == ".." ||
            name.find_first_of("/\\") != S::npos || filename.has_root_path() ||
            filename.filename() != filename)
            throw std::invalid_argument("invalid transferred member filename");
        const auto destination = root / filename;
        if (!destinations.insert(destination).second)
            throw std::invalid_argument("duplicate transferred member filename");
        auto data = ::cw::data::xml2etree(path, "", std::nullopt, std::nullopt, true);
        if (!data || !data->getroot())
            throw std::runtime_error("scenario log member XML cannot be read");
        members.push_back({fs::u8path(path), destination, std::move(data)});
    }
    for (auto& member : members) {
        member.data->m_fpath = generic(member.destination);
        rewrite(member.data);
        // Python の書き込みは FileSync を経由する場合があ
        // る。 次の処理は同じファイルの存在確認と名前変更を行うため、予
        // 約した出力先ではなく書き込み完了後の状態を参照する必要がある。
        if (::cw::g_fsync) ::cw::g_fsync->sync();
        if (!fs::is_regular_file(member.destination))
            throw std::runtime_error("scenario log member was not written");
    }
    // 全出力を書き終えてから古い名前を取り除き、別メンバーの出
    // 力先でもある元の名前は削除しない。 対象は展開済みの一時
    // ログ内の個別 XML であり、元の宿や Party.wsl
    // ではない。 失敗した場合はアーカイブを再作成しない。
    for (const auto& member : members) {
        if (!fs::exists(member.source)) continue;
        const bool retained = std::any_of(destinations.begin(), destinations.end(), [&](const auto& path) {
            std::error_code error;
            return path == member.source || fs::equivalent(path, member.source, error);
        });
        if (!retained) fs::remove(member.source);
    }
}

void TransferYadoDataDialog::transfer_party(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::header::PartyHeader> arg_header, std::shared_ptr<::cw::yadodb::YadoDB> arg_yadodb, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    if (!arg_header || !arg_counter) throw std::invalid_argument("transfer_party requires a header and counter");
    const auto source_path = value_string(arg_header->m_fpath);
    if (source_path.empty()) throw std::invalid_argument("party header has no path");
    const auto source_dir = fs::u8path(source_path).parent_path();
    const auto destination_dir = fs::u8path(duplicate_path(replace_root(generic(source_dir), arg_fromyado, arg_toyado)));
    fs::create_directories(destination_dir);

    std::map<S, S> rename_table;
    I order = 0;
    auto source_carddb = std::make_shared<::cw::yadodb::YadoDB>();
    source_carddb->initialize(generic(source_dir), ::cw::yadodb::g_PARTY);
    auto cards = source_carddb->get_cards();
    source_carddb->close();
    auto destination_carddb = std::make_shared<::cw::yadodb::YadoDB>();
    destination_carddb->initialize(generic(destination_dir), ::cw::yadodb::g_PARTY);
    for (const auto& card_header : cards) {
        if (!card_header) continue;
        const auto card_path = value_string(card_header->m_fpath);
        auto data = ::cw::data::xml2etree(card_path, "", std::nullopt, std::nullopt, true);
        if (!data || !data->getroot()) continue;
        data->m_fpath.clear();
        transfer_card(arg_fromyado, arg_toyado, data, std::nullopt, arg_counter);
        const auto basename = generic(fs::u8path(card_path).filename());
        const auto destination = duplicate_path(generic((destination_dir / fs::u8path(card_header->m_type) / fs::u8path(basename))));
        ensure_parent(destination);
        data->write_file(destination);
        destination_carddb->insert_card(destination, false, order++);
        rename_table[basename] = generic(fs::u8path(destination).filename());
        arg_counter->increment_progress();
    }
    destination_carddb->commit();
    destination_carddb->close();

    auto party_data = ::cw::data::xml2etree(source_path, "", std::nullopt, std::nullopt, true);
    if (!party_data || !party_data->getroot()) throw std::runtime_error("party XML cannot be read");
    const auto members = arg_header->get_memberpaths(arg_fromyado);
    for (std::size_t i = 0; i < members.size(); ++i) {
        if (members[i].empty()) continue;
        auto member_data = ::cw::data::xml2etree(members[i], "", std::nullopt, std::nullopt, true);
        if (!member_data || !member_data->getroot()) continue;
        if (const auto personal = member_data->find("PersonalCards"); personal && *personal) {
            for (const auto& card : (*personal)->m_children) if (card) {
                const auto found = rename_table.find(card->m_text);
                if (found != rename_table.end()) card->m_text = found->second;
            }
        }
        const auto old_name = generic(fs::u8path(members[i]).stem());
        const auto new_path = transfer_adventurer(arg_fromyado, arg_toyado, member_data, arg_yadodb, arg_counter, false);
        const auto new_name = generic(fs::u8path(new_path).stem());
        const auto member = party_data->find("Property/Members/Member[" + std::to_string(i + 1) + "]");
        if (member && *member) (*member)->m_text = new_name;
        arg_counter->m_membertable[old_name] = new_name;
    }
    const auto party_destination = generic((destination_dir / "Party.xml"));
    party_data->write_file(party_destination);
    arg_counter->increment_progress();
    if (arg_yadodb) arg_yadodb->insert_party(party_destination, false);

    const auto wsl = fs::u8path(source_path).replace_extension(".wsl");
    S extracted_log;
    TemporaryTreeCleanup temporary_log;
    if (fs::is_regular_file(wsl)) {
        // Python と同様、Party.wsl をプロセスの一時ディレクトリーへ展開
        // して XML を書き換え、 更新した ScenarioLog を再び圧縮する。
        extracted_log = ::cw::util::decompress_zip(generic(wsl), runtime_tempdir(), "ScenarioLog",
                                                    std::nullopt, std::nullopt, false, std::nullopt);
        temporary_log.path = extracted_log;
        temporary_log.enabled = !extracted_log.empty();
    }
    if (!extracted_log.empty() && fs::is_directory(fs::u8path(extracted_log))) {
        const auto log_dir = fs::u8path(extracted_log);
        const auto scenario_log = log_dir / "ScenarioLog.xml";
        if (fs::is_regular_file(scenario_log)) {
            if (const auto log = ::cw::data::xml2etree(generic(scenario_log), "", std::nullopt, std::nullopt, true); log) {
                rewrite_scenario_log(log, arg_counter->m_imgpaths);
                log->write_file(generic(scenario_log));
            }
        }
        const auto face_log = log_dir / "Face" / "Log.xml";
        if (fs::is_regular_file(face_log)) {
            if (const auto log = ::cw::data::xml2etree(generic(face_log), "", std::nullopt, std::nullopt, true); log) {
                rewrite_face_log(log, arg_counter->m_imgpaths, arg_counter->m_membertable);
                log->write_file(generic(face_log));
            }
        }
        const auto party_log = log_dir / "Party";
        for (const auto& path : xml_files(party_log)) {
            auto log = ::cw::data::xml2etree(path, "", std::nullopt, std::nullopt, true);
            if (!log) continue;
            for (const auto& member : log->find_exists("Property/Members")->m_children) if (member) {
                const auto found = arg_counter->m_membertable.find(member->m_text);
                if (found == arg_counter->m_membertable.end()) {
                    throw std::out_of_range("scenario log member was not transferred: " + member->m_text);
                }
                member->m_text = found->second;
            }
            log->write_file(path);
            // Python と同様、このディレクトリーの最初の Party XML だけを処理する。
            break;
        }
        rewrite_log_members(generic(log_dir / "Members"), arg_counter->m_membertable, [&](ET member) {
            transfer_adventurer(arg_fromyado, arg_toyado, std::move(member), std::nullopt, arg_counter, true);
        });
        // 上の ScenarioLog・Face/Log・Party XML は同じ予約型の書
        // き込み処理を使う。 展開ディレクトリーを圧縮する前に、それらの書き込みを完了する。
        if (::cw::g_fsync) ::cw::g_fsync->sync();
        const auto out_wsl = generic((destination_dir / "Party.wsl"));
        ::cw::util::compress_zip(generic(log_dir), out_wsl, true);
    }
    arg_counter->increment_progress();
}

void TransferYadoDataDialog::transfer_album(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::vector<std::shared_ptr<::cw::header::AdventurerHeader>> arg_album, std::shared_ptr<::cw::yadodb::YadoDB> arg_yadodb, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    if (!arg_counter) throw std::invalid_argument("transfer_album requires a transfer counter");
    for (const auto& header : arg_album) {
        if (!header) continue;
        const auto source_path = value_string(header->m_fpath);
        auto data = ::cw::data::xml2etree(source_path, "", std::nullopt, std::nullopt, true);
        if (!data || !data->getroot()) throw std::runtime_error("album XML cannot be read");
        const auto name = data->gettext("Property/Name", "");
        // アルバム素材の出力先は、意図的に Python の生のパスに従う。
        // Python が重複確認するのは XML のファイルパスだけである。
        const auto destination_dir = generic((fs::u8path(arg_toyado) / "Material" / "Album" / fs::u8path(name.empty() ? "noname" : name)));
        copy_materials(data->find_exists("Property"), destination_dir, arg_fromyado, arg_toyado, arg_counter->m_imgpaths, data->getbool(".", ::cw::lib::Value("scaledimage"), false), true);
        const auto destination = duplicate_path(replace_root(source_path, arg_fromyado, arg_toyado));
        ensure_parent(destination);
        data->write_file(destination);
        if (arg_yadodb) arg_yadodb->insert_adventurer(destination, true, false);
        arg_counter->increment_progress();
    }
}

::cw::lib::String TransferYadoDataDialog::transfer_adventurer(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::data::CWPyElementTree> arg_data, std::optional<std::shared_ptr<::cw::yadodb::YadoDB>> arg_yadodb, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter, bool arg_overwrite)
{
    if (!arg_data || !arg_data->getroot() || !arg_counter) throw std::invalid_argument("transfer_adventurer requires XML and counter");
    const auto name = arg_data->gettext("Property/Name", "");
    const auto destination_dir = duplicate_path(generic((fs::u8path(arg_toyado) / "Material" / "Adventurer" / fs::u8path(name.empty() ? "noname" : name))));
    copy_materials(arg_data->find_exists("Property"), destination_dir, arg_fromyado, arg_toyado, arg_counter->m_imgpaths, arg_data->getbool(".", ::cw::lib::Value("scaledimage"), false), true);
    auto destination = tree_path(arg_data);
    if (!arg_overwrite) destination = duplicate_path(replace_root(destination, arg_fromyado, arg_toyado));
    if (destination.empty()) destination = generic((fs::u8path(destination_dir) / fs::u8path((name.empty() ? "noname" : name) + ".xml")));
    if (!arg_overwrite) arg_data->m_fpath = destination;
    for (const auto& tag : {S{"SkillCards"}, S{"ItemCards"}, S{"BeastCards"}}) {
        const auto cards = arg_data->find(tag);
        if (!cards || !*cards) continue;
        for (const auto& card : (*cards)->m_children) {
            if (!card) continue;
            card->m_fpath.clear();
            transfer_card(arg_fromyado, arg_toyado, std::make_shared<::cw::data::CWPyElementTree>(card), std::nullopt, arg_counter);
        }
    }
    ensure_parent(destination);
    arg_data->write_file(destination);
    if (arg_yadodb && *arg_yadodb) (*arg_yadodb)->insert_adventurer(destination, false, false);
    if (!arg_overwrite) arg_counter->increment_progress();
    return destination;
}

void TransferYadoDataDialog::transfer_card(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::data::CWPyElementTree> arg_data, std::optional<std::shared_ptr<::cw::yadodb::YadoDB>> arg_yadodb, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    if (!arg_data || !arg_data->getroot() || !arg_counter) throw std::invalid_argument("transfer_card requires XML and counter");
    const auto materials = arg_data->find("Property/Materials");
    S destination_dir;
    if (materials && *materials) {
        destination_dir = generic((fs::u8path(arg_toyado) / fs::u8path((*materials)->m_text.empty() ? S{"noname"} : (*materials)->m_text)));
    } else {
        // Python の gettext の既定値は、要素がない場合だけに適用
        // する。 明示的に空の Name は、末尾のパス要素も空のままにする。
        const auto name = arg_data->gettext("Property/Name", "noname");
        destination_dir = ::cw::util::join_paths({::cw::lib::Value(arg_toyado),
            ::cw::lib::Value("Material"), ::cw::lib::Value(arg_data->getroot()->m_tag),
            ::cw::lib::Value(name)});
    }
    destination_dir = duplicate_path(destination_dir);
    const auto scenario_card = arg_data->getbool(".", ::cw::lib::Value("scenariocard"), false);
    if (!scenario_card) copy_materials(arg_data->getroot(), destination_dir, arg_fromyado, arg_toyado, arg_counter->m_imgpaths, arg_data->getbool(".", ::cw::lib::Value("scaledimage"), false), false);
    auto destination = tree_path(arg_data);
    if (!destination.empty()) {
        destination = duplicate_path(replace_root(destination, arg_fromyado, arg_toyado));
        ensure_parent(destination);
        arg_data->write_file(destination);
        if (arg_yadodb && *arg_yadodb) {
            (*arg_yadodb)->insert_card(destination, false);
            arg_counter->increment_progress();
        }
    }
}

void TransferYadoDataDialog::transfer_partyrecord(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>> arg_partyrecord, std::shared_ptr<::cw::yadodb::YadoDB> arg_yadodb, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    if (!arg_counter) throw std::invalid_argument("transfer_partyrecord requires a transfer counter");
    for (const auto& header : arg_partyrecord) {
        if (!header) continue;
        const auto source = value_string(header->m_fpath);
        auto data = ::cw::data::xml2etree(source, "", std::nullopt, std::nullopt, true);
        if (!data || !data->getroot()) throw std::runtime_error("party record XML cannot be read");
        if (const auto members = data->find("Property/Members"); members && *members) {
            for (const auto& member : (*members)->m_children) if (member) {
                const auto found = arg_counter->m_membertable.find(member->m_text);
                if (found != arg_counter->m_membertable.end()) member->m_text = found->second;
            }
        }
        const auto destination = duplicate_path(replace_root(source, arg_fromyado, arg_toyado));
        ensure_parent(destination);
        data->write_file(destination);
        if (arg_yadodb) arg_yadodb->insert_partyrecord(destination, false);
        arg_counter->increment_progress();
    }
}

void TransferYadoDataDialog::transfer_savedjpdcimage(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::header::SavedJPDCImageHeader> arg_header, std::shared_ptr<::cw::yadodb::YadoDB> arg_yadodb, std::map<std::tuple<::cw::lib::String, ::cw::lib::String>, std::shared_ptr<::cw::header::SavedJPDCImageHeader>> arg_table, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    if (!arg_header || !arg_counter) throw std::invalid_argument("transfer_savedjpdcimage requires a header and counter");
    const auto dpath = value_string(arg_header->m_dpath);
    if (dpath.empty()) throw std::invalid_argument("saved JPDC header has no directory path");
    const auto key = std::make_tuple(arg_header->m_scenarioname, arg_header->m_scenarioauthor);
    const auto source_dir = fs::u8path(arg_fromyado) / "SavedJPDCImage" / fs::u8path(dpath);
    auto destination_dir = fs::u8path(arg_toyado) / "SavedJPDCImage" / fs::u8path(dpath);
    destination_dir = fs::u8path(duplicate_path(generic(destination_dir)));
    const auto existing = arg_table.find(key);
    const auto relative = generic(fs::relative(destination_dir, fs::u8path(arg_toyado) / "SavedJPDCImage"));
    const auto source_xml = source_dir / "SavedJPDCImage.xml";
    const auto destination_xml = destination_dir / "SavedJPDCImage.xml";
    // 出力先や既存の同じシナリオの画像に触る前に、入力元を
    // 解析・書き換えする。 入力が不正な場合、転送失敗の副
    // 作用で以前に保存済みのディレクトリーを削除しない。
    auto data = ::cw::data::xml2etree(generic(source_xml), "", std::nullopt, std::nullopt, true);
    if (!data || !data->getroot()) throw std::runtime_error("saved JPDC XML cannot be read");
    data->edit("Materials", relative, std::optional<S>("dpath"));
    try {
        copy_tree(source_dir, destination_dir);
        data->write_file(generic(destination_xml));
    } catch (...) {
        std::error_code cleanup_error;
        fs::remove_all(destination_dir, cleanup_error);
        throw;
    }
    if (existing != arg_table.end() && existing->second) {
        const auto old = value_string(existing->second->m_dpath);
        if (!old.empty()) {
            const auto old_dir = fs::u8path(arg_toyado) / "SavedJPDCImage" / fs::u8path(old);
            std::error_code error;
            fs::remove_all(old_dir, error);
            if (error) {
                std::error_code cleanup_error;
                fs::remove_all(destination_dir, cleanup_error);
                throw std::runtime_error("old saved JPDC image cannot be removed: " + error.message());
            }
            if (arg_yadodb) arg_yadodb->delete_savedjpdcimage(generic((fs::u8path("SavedJPDCImage") / fs::u8path(old) / "SavedJPDCImage.xml")), false);
        }
    }
    // Python は渡されたヘッダーを出力先用に書き換える
    // が、ネイティブ版では出力先用ヘッダーを別に持つ。 この
    // 入力元の表は再試行や後の転送でも使うため、そのパスを書
    // き換えると、次回に出力先を入力元として読んでしまう。
    auto destination_header = std::make_shared<::cw::header::SavedJPDCImageHeader>();
    destination_header->m_dpath = arg_header->m_dpath;
    destination_header->m_fpath = arg_header->m_fpath;
    destination_header->m_fpaths = arg_header->m_fpaths;
    destination_header->m_scenarioauthor = arg_header->m_scenarioauthor;
    destination_header->m_scenarioname = arg_header->m_scenarioname;
    destination_header->m_fpaths_typed = arg_header->m_fpaths_typed;
    set_path_value(destination_header->m_dpath, relative);
    destination_header->m_fpath = ::cw::lib::Value(generic(destination_xml));
    if (arg_yadodb) arg_yadodb->insert_savedjpdcimageheader(destination_header, false);
    arg_counter->increment_progress();
}

void TransferYadoDataDialog::transfer_savedvariables(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::yadodb::YadoDB> arg_yadodb, std::tuple<std::tuple<::cw::lib::String, ::cw::lib::String>, std::shared_ptr<::cw::data::CWPyElement>, bool> arg_d, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    (void)arg_fromyado;
    (void)arg_toyado;
    (void)arg_yadodb;
    if (!arg_counter) throw std::invalid_argument("transfer_savedvariables requires a transfer counter");
    if (!arg_counter->m_environment) throw std::runtime_error("transfer_savedvariables requires destination Environment.xml");

    const auto key = std::get<0>(arg_d);
    const auto source = std::get<1>(arg_d);
    (void)std::get<2>(arg_d);
    if (!source) throw std::invalid_argument("transfer_savedvariables requires source Variables");

    std::shared_ptr<::cw::data::CWPyElement> target;
    const auto existing = arg_counter->m_saved_variables.find(key);
    if (existing != arg_counter->m_saved_variables.end()) {
        target = std::get<0>(existing->second);
        if (!target) throw std::runtime_error("saved variable table contains a null element");
        target->clear();
    } else {
        auto saved = arg_counter->m_environment->find("SavedVariables");
        auto saved_element = saved && *saved ? *saved : nullptr;
        if (!saved_element) {
            saved_element = ::cw::data::make_element("SavedVariables");
            const auto root = arg_counter->m_environment->getroot();
            if (!root) throw std::runtime_error("destination Environment.xml has no root");
            root->append(saved_element);
        }
        target = ::cw::data::make_element("Variables");
        saved_element->append(target);
    }
    target->set("scenario", std::get<0>(key));
    target->set("author", std::get<1>(key));
    for (const auto& variable : source->m_children) target->append(variable);
    // Py と同様、カウンターの出力先検索表は最初のスナップショットを維持す
    // る。 最初になかったキーは繰り返されても呼び出しごとに新しい XML
    // 項目を追加し、 ここで追加した XML から表を再構築・更新しない。
    arg_counter->m_environment->m_is_edited = true;
    arg_counter->increment_progress();
}

void TransferYadoDataDialog::transfer_skinvariables(::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::shared_ptr<::cw::yadodb::YadoDB> arg_yadodb, std::tuple<::cw::lib::String, std::shared_ptr<::cw::data::CWPyElement>, bool, ::cw::lib::String, ::cw::lib::String> arg_d, std::shared_ptr<::cw::dialog::transfer::_TransferThread> arg_counter)
{
    (void)arg_fromyado;
    (void)arg_toyado;
    (void)arg_yadodb;
    if (!arg_counter) throw std::invalid_argument("transfer_skinvariables requires a transfer counter");

    const auto key = std::get<0>(arg_d);
    const auto source = std::get<1>(arg_d);
    (void)std::get<2>(arg_d);
    (void)std::get<3>(arg_d);
    (void)std::get<4>(arg_d);
    if (!source) throw std::invalid_argument("transfer_skinvariables requires source Variables");

    if (!arg_counter->m_skin_vars) {
        const auto path = generic((fs::u8path(arg_toyado) / "SkinVariables.xml"));
        if (!fs::is_regular_file(fs::u8path(path))) ::cw::xmlcreater::create_skinvariables(path);
        auto tree = ::cw::data::xml2etree(path, "", std::nullopt, std::nullopt, true);
        if (!tree || !tree->getroot()) throw std::runtime_error("SkinVariables.xml cannot be created");
        arg_counter->m_skin_vars = SkinVariables{tree, ::cw::data::YadoData::get_savedvariables_with_skin(tree->getroot())};
    }
    auto& skin_variables = *arg_counter->m_skin_vars;
    const auto tree = std::get<0>(skin_variables);
    if (!tree || !tree->getroot()) throw std::runtime_error("SkinVariables tree has no root");
    auto& variables = std::get<1>(skin_variables);

    std::shared_ptr<::cw::data::CWPyElement> target;
    const auto existing = variables.find(key);
    if (existing != variables.end()) {
        target = std::get<0>(existing->second);
        if (!target) throw std::runtime_error("skin variable table contains a null element");
        target->clear();
    } else {
        target = ::cw::data::make_element("Variables");
        tree->getroot()->append(target);
    }
    target->set("key", key);
    for (const auto& variable : source->m_children) target->append(variable);
    // 保存済みシナリオ変数と同様、Py は新しいキーを初期の skin_vars 表
    // へ追加しない。 同じ新規キーが繰り返されても、別々の XML 項目として残す。
    tree->m_is_edited = true;
    arg_counter->increment_progress();
}

void TransferYadoDataDialog::OnCancel(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(!visible || m_transfer_running) return;
    (void)arg_event;
    transfer_play_sound("click");
    m_cancelled = true;
    m_modal_result = 0;
    visible = false;
}

void TransferYadoDataDialog::OnPaint(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    sync_ui();
}

void TransferYadoDataDialog::_bind()
{
    bind_ui();
}

void TransferYadoDataDialog::_do_layout()
{
    sync_ui();
}

void TransferYadoDataDialog::OnListItemChecked(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if(!visible || m_transfer_running) return;
    if (arg_event && arg_event->id >= 0 && arg_event->id < static_cast<I>(m_checked.size())) {
        const auto index=static_cast<std::size_t>(arg_event->id);
        const bool checked=!m_checked[index];m_checked[index]=checked;
        // Python の CheckableListCtrl と同様、選択行のチ
        // ェック変更は他の選択行へ反映するが、 無関係な未選択行には適用しない。
        if(index<m_selected.size() && m_selected[index])
            for(std::size_t i=0;i<m_checked.size() && i<m_selected.size();++i)
                if(m_selected[i])m_checked[i]=checked;
        transfer_play_sound("page");
    }
    _enable_btn();
}

void TransferYadoDataDialog::bind_ui()
{
    if (!m_ui_backend) return;
    const auto token = reinterpret_cast<TransferUiBackend::Token>(this);
    m_ui_backend->bind(token, {
        [this](I index) { auto event=std::make_shared<::cw::lib::Window>();event->id=index;OnFromYado(event); },
        [this](I index) { auto event=std::make_shared<::cw::lib::Window>();event->id=index;OnToYado(event); },
        [this](I index) { auto event=std::make_shared<::cw::lib::Window>();event->id=index;OnListItemChecked(event); },
        [this] { OnOk(nullptr); }, [this] { OnCancel(nullptr); }
    });
}

void TransferYadoDataDialog::sync_ui()
{
    if (!m_ui_backend) return;
    TransferUiState state;
    state.yado_names = m_yadonames;
    state.checked = m_checked;
    state.from_index = m_from_index;
    state.to_index = m_to_index;
    state.ok_enabled = m_ok_enabled;
    state.list_enabled = !m_data.empty();
    state.parent_native_handle = m_parent ? m_parent->native_handle : 0;
    state.visible = visible;
    state.item_labels.reserve(m_data.size());
    state.item_icons.reserve(m_data.size());
    for (const auto& item : m_data) {
        state.item_labels.push_back(transfer_item_label(item));
        state.item_icons.push_back(transfer_item_icon(item));
    }
    if (m_data.empty())
        state.item_labels.push_back(transfer_message("transfer_no_item", "転送可能な項目はありません"));
    m_ui_backend->sync(reinterpret_cast<TransferUiBackend::Token>(this), state);
}

namespace {
using TransferRect = ::cw::lib::Rect;
constexpr I transfer_row_height=20, transfer_popup_rows=8;
struct TransferLayout {
    I width{310},height{413},label_width{},rows{},content_width{},max_x{},max_y{};
    TransferRect choices[2],list,viewport,vertical,horizontal,popup,popup_track;
};
TransferLayout transfer_layout(const TransferYadoDataDialog& dialog) {
    TransferLayout l;
    const auto label=dialog.dialog_font("dlgmsg2",16);
    const auto combo=dialog.dialog_font("combo",16);
    const auto font=dialog.dialog_font("combo",14);
    const auto measure=[](const S& text,const auto& f) {
        const auto width=::cw::lib::ui::label_width(text,f.pixels,f.bold,f.face,f.italic);
        // 配置・入力は論理座標のままとし、まず実際の最終ピクセルで文字を計測する。
        return static_cast<I>(std::ceil(width/std::max(1.0,::cw::g_UP_WIN)));
    };
    l.label_width=std::max(measure(transfer_message("transfer_from_base","転送元:"),label),
                           measure(transfer_message("transfer_to_base","転送先:"),label))+6;
    I choice_width=100;
    for(const auto& name:dialog.m_yadonames) choice_width=std::max(choice_width,measure(name,combo)+28);
    l.width=std::max<I>(310,l.label_width+choice_width+10);
    l.choices[0]={5+l.label_width,5,l.width-l.label_width-10,24};
    l.choices[1]={5+l.label_width,34,l.width-l.label_width-10,24};
    l.list={5,63,l.width-10,300};
    l.content_width=46;
    for(const auto& item:dialog.m_data) l.content_width=std::max(l.content_width,measure(transfer_item_label(item),font)+48);
    const I count=static_cast<I>(dialog.m_data.size());
    bool vertical=count>296/transfer_row_height;
    bool horizontal=l.content_width>l.width-14-(vertical?14:0);
    vertical=count>(296-(horizontal?14:0))/transfer_row_height;
    horizontal=l.content_width>l.width-14-(vertical?14:0);
    l.viewport={7,65,l.width-14-(vertical?14:0),296-(horizontal?14:0)};
    l.rows=std::max<I>(1,l.viewport.height/transfer_row_height);
    l.max_y=std::max<I>(0,count-l.rows);
    l.max_x=std::max<I>(0,l.content_width-l.viewport.width);
    if(vertical) l.vertical={l.viewport.x+l.viewport.width,65,14,l.viewport.height};
    if(horizontal) l.horizontal={7,l.viewport.y+l.viewport.height,l.viewport.width,14};
    const I choice=std::clamp<I>(dialog.m_open_combo,0,1);
    const I shown=std::min<I>(transfer_popup_rows,dialog.m_yadonames.size());
    l.popup={l.choices[choice].x,l.choices[choice].y+24,l.choices[choice].width,shown*24+2};
    if(dialog.m_yadonames.size()>transfer_popup_rows)
        l.popup_track={l.popup.x+l.popup.width-14,l.popup.y+1,13,shown*24};
    return l;
}
bool transfer_contains(const TransferRect& r,double x,double y) {
    return r.width>0 && r.height>0 && x>=r.x && y>=r.y && x<r.x+r.width && y<r.y+r.height;
}
TransferRect transfer_thumb(TransferRect track,I offset,I maximum,I page,bool horizontal=false) {
    if(maximum<=0) return track;
    const I length=horizontal?track.width:track.height;
    const I size=std::min(length,std::max<I>(14,length*page/(maximum+page)));
    const I at=std::clamp<I>(offset,0,maximum)*(length-size)/maximum;
    if(horizontal){track.x+=at;track.width=size;} else {track.y+=at;track.height=size;}
    return track;
}
void transfer_outline(const std::shared_ptr<::cw::lib::Surface>& surface,TransferRect r) {
    using ::cw::lib::ui::fill_rect;
    for(I x=r.x+2;x<r.x+r.width-2;x+=2) {
        fill_rect(surface,{x,r.y+2,1,1},{30,30,30,255});
        fill_rect(surface,{x,r.y+r.height-3,1,1},{30,30,30,255});
    }
    for(I y=r.y+2;y<r.y+r.height-2;y+=2) {
        fill_rect(surface,{r.x+2,y,1,1},{30,30,30,255});
        fill_rect(surface,{r.x+r.width-3,y,1,1},{30,30,30,255});
    }
}
}

::cw::lib::ui::FontStyle TransferYadoDataDialog::dialog_font(const S& role,I pixels) const
{
    return ::cw::lib::ui::configured_wx_font(role,pixels);
}

::cw::dialog::DialogPresentation TransferYadoDataDialog::dialog_presentation()
{
    using Action=::cw::dialog::DialogPresentationAction;
    using namespace ::cw::lib::ui;
    // 共通の一つの UI として、最終ピ
    // クセル単位の完全な描画面を作る。
    // ラスター化済みの文字を拡大しない。
    const double scale=std::max(1.0,::cw::g_UP_WIN);
    const auto pixel=[&](I value){return static_cast<I>(std::lround(value*scale));};
    const auto rect=[&](TransferRect r){return TransferRect{
        pixel(r.x),pixel(r.y),pixel(r.x+r.width)-pixel(r.x),pixel(r.y+r.height)-pixel(r.y)};};
    bool painting=true;
    const auto fill_rect=[&](const auto& destination,TransferRect r,::cw::lib::Color color){
        if(painting) ::cw::lib::ui::fill_rect(destination,rect(r),color);
    };
    const auto draw_sunken_border=[&](const auto& destination,TransferRect r){
        if(painting) ::cw::lib::ui::draw_sunken_border(destination,rect(r));
    };
    const auto outline=[&](const auto& destination,TransferRect r){
        if(painting) transfer_outline(destination,rect(r));
    };
    const auto l=transfer_layout(*this);
    m_scroll_offset=std::clamp<I>(m_scroll_offset,0,l.max_y);
    m_horizontal_offset=std::clamp<I>(m_horizontal_offset,0,l.max_x);
    if(m_selected.size()!=m_data.size()) m_selected.assign(m_data.size(),false);
    auto& retained=dialog_retained_surface();
    const ::cw::lib::Size final_size{pixel(l.width),pixel(l.height)};
    const bool full=retained.needs_full(final_size);
    if(full) {
        retained.allocate(final_size,{240,240,240,255});
        if(const auto tile=resource_surface_for_window(resource_dialog_background("CAUTION"))) {
            for(I y=0;y<retained.surface->size.height;y+=std::max<I>(1,tile->size.height))
                for(I x=0;x<retained.surface->size.width;x+=std::max<I>(1,tile->size.width)) blend_surface(retained.surface,tile,x,y);
        }
        retained.capture_base();
    }
    const auto mix=[](std::uint64_t& seed,std::uint64_t value){seed^=value+0x9e3779b97f4a7c15ULL+(seed<<6U)+(seed>>2U);};
    std::uint64_t choices_signature{};mix(choices_signature,static_cast<std::uint64_t>(m_from_index+1));
    mix(choices_signature,static_cast<std::uint64_t>(m_to_index+1));mix(choices_signature,static_cast<std::uint64_t>(m_focus+1));
    mix(choices_signature,static_cast<std::uint64_t>(m_open_combo+1));
    for(const auto& name:m_yadonames)mix(choices_signature,std::hash<S>{}(name));
    std::uint64_t list_signature{};mix(list_signature,static_cast<std::uint64_t>(m_scroll_offset));
    mix(list_signature,static_cast<std::uint64_t>(m_horizontal_offset));mix(list_signature,static_cast<std::uint64_t>(m_row+1));
    mix(list_signature,static_cast<std::uint64_t>(m_focus+1));mix(list_signature,static_cast<std::uint64_t>(m_open_combo+1));
    for(std::size_t i=0;i<m_data.size();++i) {mix(list_signature,std::hash<S>{}(transfer_item_label(m_data[i])));
        if(i<m_selected.size())mix(list_signature,static_cast<std::uint64_t>(m_selected[i]));
        if(i<m_checked.size())mix(list_signature,static_cast<std::uint64_t>(m_checked[i]));}
    std::uint64_t footer_signature{};mix(footer_signature,static_cast<std::uint64_t>(m_ok_enabled));
    mix(footer_signature,static_cast<std::uint64_t>(m_focus+1));mix(footer_signature,static_cast<std::uint64_t>(m_transfer_running));
    mix(footer_signature,static_cast<std::uint64_t>(visible));mix(footer_signature,static_cast<std::uint64_t>(m_open_combo+1));
    const bool paint_choices=retained.component_changed("transfer.choices",rect({0,0,l.width,l.list.y}),choices_signature);
    const bool paint_list=retained.component_changed("transfer.list",rect({0,l.list.y,l.width,373-l.list.y}),list_signature);
    const bool paint_footer=retained.component_changed("transfer.footer",rect({0,373,l.width,l.height-373}),footer_signature);
    bool paint_popup=false;
    if(m_open_combo>=0 && !m_yadonames.empty()) {
        std::uint64_t popup_signature=static_cast<std::uint64_t>(m_open_combo+1);mix(popup_signature,static_cast<std::uint64_t>(m_combo_cursor+1));
        mix(popup_signature,static_cast<std::uint64_t>(m_combo_offset+1));
        paint_popup=retained.component_changed("transfer.popup",rect(l.popup),popup_signature);
    } else (void)retained.remove_component("transfer.popup");
    retained.restore_dirty();
    auto surface=retained.surface;
    ::cw::dialog::DialogPresentation result;
    result.route="TRANSFER_YADO_DATA";
    result.wants_text_input=visible && !m_transfer_running &&
        (m_focus<2?!m_yadonames.empty():m_focus==2 && !m_data.empty());
    result.text_input_hardware_only=true;
    result.title=transfer_message("transfer_title","カードとブックマークの転送");
    const auto font=dialog_font("combo",14),combo=dialog_font("combo",16),label=dialog_font("dlgmsg",16);
    const auto text=[&](const S& value,TransferRect r,const FontStyle& style,bool selected=false,I shift=0,
                        bool centered=false,bool enabled=true) {
        if(!painting)return;
        // 斜体のはみ出しも含め、最終サイズでラスター化してから切り取る。
        // ラベル・ポップアップ項目・行・ボタン見出しに同じ計測規則を使う。
        const auto bounds=rect(r);
        if(bounds.width<=0 || bounds.height<=0)return;
        auto ink=std::make_shared<::cw::lib::Surface>();ink->size={bounds.width,bounds.height};
        ink->rgba.assign(bounds.width*bounds.height*4,0);
        const auto selection=system_selection_colours();
        const auto color=!enabled?std::tuple<I,I,I>{100,100,100}:
            selected?std::tuple<I,I,I>{selection.text.r,selection.text.g,selection.text.b}:std::tuple<I,I,I>{0,0,0};
        const auto glyph=render_label(value,style.pixels,style.bold,color,style.face,style.italic);
        if(glyph) {
            const I x=centered?(bounds.width-glyph->size.width)/2:pixel(3-shift);
            const I y=(bounds.height-glyph->size.height)/2;
            blend_surface(ink,glyph,x,y);
        }
        blend_surface(surface,ink,bounds.x,bounds.y);
    };
    const auto hit=[&](Action action,int index,TransferRect r,bool continuous=false,const S& name=S{}) {
        const auto bounds=rect(r);
        result.controls.push_back({action,index,static_cast<float>(bounds.x),static_cast<float>(bounds.y),
            static_cast<float>(bounds.width),static_cast<float>(bounds.height),true,continuous,name});
    };
    const auto scrollbar=[&](TransferRect track,I at,I maximum,I page,int id,bool horizontal=false) {
        if(track.width<=0 || track.height<=0)return;
        fill_rect(surface,track,{230,230,230,255});
        const auto thumb=transfer_thumb(track,at,maximum,page,horizontal);
        fill_rect(surface,thumb,{168,168,168,255});
        draw_sunken_border(surface,thumb);
        hit(Action::Auxiliary,id,track,true,"スクロール");
    };
    painting=paint_choices;
    for(int n=0;n<2;++n) {
        const auto r=l.choices[n];const I selected=n==0?m_from_index:m_to_index;
        text(transfer_message(n==0?"transfer_from_base":"transfer_to_base",n==0?"転送元:":"転送先:"),
             {5,r.y,l.label_width-3,24},label,false,3);
        fill_rect(surface,r,{255,255,255,255});draw_sunken_border(surface,r);
        if(selected>=0 && selected<static_cast<I>(m_yadonames.size()))
            text(m_yadonames[selected],{r.x+2,r.y+2,r.width-23,r.height-4},combo);
        for(I i=0;i<4;++i) fill_rect(surface,{r.x+r.width-15+i,r.y+10+i,7-2*i,1},{0,0,0,255});
        hit(Action::Select,-1-n,r,false,n==0?"転送元":"転送先");
        result.controls.back().enabled=!m_yadonames.empty();
        if(m_focus==n) outline(surface,r);
    }
    painting=paint_list;
    fill_rect(surface,l.list,{255,255,255,255});draw_sunken_border(surface,l.list);
    for(I row=0;row<l.rows && row+m_scroll_offset<static_cast<I>(m_data.size());++row) {
        const I i=row+m_scroll_offset,y=l.viewport.y+row*transfer_row_height;
        const bool selected=m_selected[i];
        const TransferRect r{l.viewport.x,y,l.viewport.width,transfer_row_height};
        if(selected)fill_rect(surface,r,system_selection_colours().background);
        hit(Action::Select,static_cast<int>(i),r,false,transfer_item_label(m_data[i]));
        // CheckableListCtrl と同様、チェックボックスは行の選択とは別に扱う。
        auto row_surface=std::make_shared<::cw::lib::Surface>();
        row_surface->size={pixel(r.width),pixel(transfer_row_height)};
        row_surface->rgba.assign(row_surface->size.width*row_surface->size.height*4,0);
        const I offset=m_horizontal_offset;
        fill_rect(row_surface,{3-offset,3,14,14},{255,255,255,255});
        draw_sunken_border(row_surface,{3-offset,3,14,14});
        if(i<static_cast<I>(m_checked.size()) && m_checked[i]) {
            for(I p=0;p<4;++p)fill_rect(row_surface,{6+p-offset,9+p,2,2},{0,80,160,255});
            for(I p=0;p<6;++p)fill_rect(row_surface,{9+p-offset,12-p,2,2},{0,80,160,255});
        }
        if(offset<21)hit(Action::Toggle,static_cast<int>(i),{r.x,y,21-offset,transfer_row_height},false,"チェック");
        const auto key=transfer_item_icon(m_data[i]);
        const auto icon=key=="BOOKMARK"?resource_dialog_surface(key):
            (::cw::g_cwpy && ::cw::g_cwpy->m_rsrc?resource_table_surface(::cw::g_cwpy->m_rsrc->m_debugs_wx,key):nullptr);
        if(icon)blend_surface(row_surface,icon,pixel(23-offset),pixel(2),pixel(16),pixel(16));
        const auto glyph=render_label(transfer_item_label(m_data[i]),font.pixels,font.bold,
            selected?std::tuple<I,I,I>{255,255,255}:std::tuple<I,I,I>{0,0,0},font.face,font.italic);
        if(glyph)blend_surface(row_surface,glyph,pixel(45-offset),(row_surface->size.height-glyph->size.height)/2);
        if(painting) blend_surface(surface,row_surface,pixel(r.x),pixel(r.y));
        if(m_focus==2 && m_row==i) outline(surface,r);
    }
    if(m_data.empty())text(transfer_message("transfer_no_item","転送可能な項目はありません"),l.viewport,font);
    scrollbar(l.vertical,m_scroll_offset,l.max_y,l.rows,1);
    scrollbar(l.horizontal,m_horizontal_offset,l.max_x,l.viewport.width,2,true);
    const I gap=(l.width-220)/3;
    const TransferRect ok{gap+5,373,100,30},cancel{2*gap+115,373,100,30};
    painting=paint_footer;
    const auto button=[&](const S& caption,TransferRect r,Action action,bool enabled) {
        if(painting) ::cw::lib::ui::draw_button_face(surface,rect(r),{enabled});
        text(caption,r,dialog_font("button",14),false,0,true,enabled);
        hit(action,0,r,false,caption);
        result.controls.back().enabled=enabled;
        result.controls.back().hover_highlight=true;
    };
    button(transfer_message("decide","決定"),ok,Action::Accept,m_ok_enabled);
    button(transfer_message("entry_cancel","キャンセル"),cancel,Action::Cancel,true);
    if(m_focus==3)outline(surface,ok);
    if(m_focus==4)outline(surface,cancel);
    if(m_open_combo>=0 && !m_yadonames.empty()) {
        painting=paint_popup;
        const I count=m_yadonames.size(),shown=std::min<I>(transfer_popup_rows,count);
        m_combo_offset=std::clamp<I>(m_combo_offset,0,std::max<I>(0,count-shown));
        m_combo_cursor=std::clamp<I>(m_combo_cursor,0,count-1);
        // モーダルのポップアップが全当たり判定を占有する。 外側のクリック
        // は閉じる操作とし、隠れた行のチェックや背後の転送開始は行わない。
        result.controls.clear();
        hit(Action::Auxiliary,-10,{0,0,l.width,l.height});
        fill_rect(surface,l.popup,{255,255,255,255});draw_sunken_border(surface,l.popup);
        for(I row=0;row<shown;++row) {
            const I i=m_combo_offset+row;
            const TransferRect r{l.popup.x+1,l.popup.y+1+row*24,l.popup.width-2-(count>shown?14:0),24};
            const bool selected=i==m_combo_cursor;
            const auto selection=system_selection_colours();
            if(selected)fill_rect(surface,r,selection.background);
            text(m_yadonames[i],r,combo,selected);
            hit(Action::Select,static_cast<int>((m_open_combo+1)*100000+i),r,false,m_yadonames[i]);
        }
        scrollbar(l.popup_track,m_combo_offset,count-shown,shown,3);
    }
    if(m_transfer_running || !visible)for(auto& control:result.controls)control.enabled=false;
    retained.finish();
    result.surface=surface; // コントロールと文字形は既に最終ウィンドウのピクセル単位である。
    result.damage=retained.damage;result.surface_revision=retained.revision;
    return result;
}

void TransferYadoDataDialog::open_combo(I combo)
{
    if(combo<0 || combo>1 || m_yadonames.empty())return;
    m_focus=static_cast<int>(combo);m_open_combo=combo;
    m_combo_cursor=std::clamp<I>(combo==0?m_from_index:m_to_index,0,m_yadonames.size()-1);
    m_combo_offset=std::max<I>(0,m_combo_cursor-transfer_popup_rows+1);
    m_scroll_drag=-1;
}
void TransferYadoDataDialog::choose_combo(I selected)
{
    const I combo=m_open_combo;
    if(selected<0 || selected>=static_cast<I>(m_yadonames.size()))return;
    m_open_combo=-1;m_scroll_drag=-1;
    auto event=std::make_shared<::cw::lib::Window>();event->id=selected;
    if(combo==0)OnFromYado(event);else if(combo==1)OnToYado(event);
}
void TransferYadoDataDialog::select_row(I row,::cw::dialog::DialogPresentationModifiers modifiers)
{
    if(row<0 || row>=static_cast<I>(m_data.size()))return;
    if(m_selected.size()!=m_data.size())m_selected.assign(m_data.size(),false);
    const bool shift=modifiers & ::cw::dialog::DialogPresentationModifierShift;
    const bool control=modifiers & ::cw::dialog::DialogPresentationModifierControl;
    if(shift) {
        if(m_anchor<0 || m_anchor>=static_cast<I>(m_data.size()))m_anchor=m_row>=0?m_row:row;
        if(!control)std::fill(m_selected.begin(),m_selected.end(),false);
        for(I i=std::min(m_anchor,row);i<=std::max(m_anchor,row);++i)m_selected[i]=true;
    } else {
        if(!control)std::fill(m_selected.begin(),m_selected.end(),false);
        m_selected[row]=control?!m_selected[row]:true;m_anchor=row;
    }
    m_row=row;m_focus=2;
    const auto l=transfer_layout(*this);
    m_scroll_offset=std::clamp<I>(m_scroll_offset,std::max<I>(0,row-l.rows+1),row);
}
void TransferYadoDataDialog::dialog_presentation_action(
    const ::cw::dialog::DialogPresentationAction action,const int index)
{
    using Action=::cw::dialog::DialogPresentationAction;
    if(!visible || m_transfer_running)return;
    if(m_type_search.composing && (action==Action::Cancel || action==Action::Accept)) {
        if(action==Action::Cancel)m_type_search.reset();
        return;
    }
    m_type_search.reset();
    if(m_open_combo>=0) {
        if(action==Action::Cancel || (action==Action::Auxiliary && index==-10)) {
            m_open_combo=-1;m_scroll_drag=-1;return;
        }
        if(action==Action::Accept){choose_combo(m_combo_cursor);return;}
        if(action==Action::Select && index>=100000 && index/100000-1==m_open_combo) {
            choose_combo(index%100000);return;
        }
        return;
    }
    if(action==Action::Cancel){OnCancel(nullptr);return;}
    if(action==Action::Accept){OnOk(nullptr);return;}
    if(action==Action::Select) {
        if(index==-1 || index==-2)open_combo(-index-1);
        else select_row(index,m_modifiers);
    } else if(action==Action::Toggle && index>=0 && index<static_cast<int>(m_checked.size())) {
        m_focus=2;m_row=index;
        auto event=std::make_shared<::cw::lib::Window>();event->id=index;OnListItemChecked(event);
    } else if(action==Action::PreviousGroup || action==Action::NextGroup) {
        const auto l=transfer_layout(*this);
        m_scroll_offset=std::clamp<I>(m_scroll_offset+(action==Action::PreviousGroup?-l.rows:l.rows),0,l.max_y);
    }
}
void TransferYadoDataDialog::dialog_presentation_modifiers(::cw::dialog::DialogPresentationModifiers modifiers)
{
    m_modifiers=modifiers;
}
void TransferYadoDataDialog::dialog_presentation_enter(::cw::dialog::DialogPresentationModifiers)
{
    if(!visible || m_transfer_running || m_type_search.composing)return;
    if(m_open_combo>=0)choose_combo(m_combo_cursor);
    else if(m_focus==4)OnCancel(nullptr);
    else OnOk(nullptr);
}
void TransferYadoDataDialog::dialog_presentation_text(const std::string& text,bool composition)
{
    if(!visible || m_transfer_running || m_focus>2)return;
    // コントロールを開く・切り替えるキーを、前方一致検索の文字としても使わない
    // 。 Backspace の転送で進行中の IME 変換を終了させない。
    if(!composition && (text=="\b" || (text==" " && !m_type_search.active())))return;
    m_type_search.composing=composition && !text.empty();
    if(composition)return;
    if(m_modifiers & (::cw::dialog::DialogPresentationModifierControl |
                      ::cw::dialog::DialogPresentationModifierAlt)) {m_type_search.reset();return;}
    if(m_open_combo>=0 || m_focus<2) {
        const auto current=m_open_combo>=0?m_combo_cursor:m_focus==0?m_from_index:m_to_index;
        const auto row=m_type_search.find(text,static_cast<int>(m_yadonames.size()),
            static_cast<int>(current),[&](int i){return m_yadonames[i];});
        if(!row)return;
        if(m_open_combo>=0) {
            m_combo_cursor=*row;
            m_combo_offset=std::clamp<I>(m_combo_offset,std::max<I>(0,*row-transfer_popup_rows+1),*row);
        } else {
            m_open_combo=m_focus;
            choose_combo(*row);
        }
    } else {
        const auto row=m_type_search.find(text,static_cast<int>(m_data.size()),static_cast<int>(m_row),
            [&](int i){return transfer_item_label(m_data[i]);});
        if(row)select_row(*row,0);
    }
    request_dialog_presentation_refresh();
}

void TransferYadoDataDialog::dialog_presentation_key(::cw::dialog::DialogPresentationKey key,bool pressed,
                                                    ::cw::dialog::DialogPresentationModifiers modifiers)
{
    using Key=::cw::dialog::DialogPresentationKey;
    m_modifiers=modifiers;
    if(!pressed || !visible || m_transfer_running)return;
    if(m_type_search.composing)return;
    if(key==Key::Space && m_focus<=2 && m_type_search.active() && !modifiers)return;
    if(!::cw::dialog::presentation_key_ascii(key) || modifiers &
        (::cw::dialog::DialogPresentationModifierControl | ::cw::dialog::DialogPresentationModifierAlt))
        m_type_search.reset();
    const bool shift=modifiers & ::cw::dialog::DialogPresentationModifierShift;
    const bool control=modifiers & ::cw::dialog::DialogPresentationModifierControl;
    const bool alt=modifiers & ::cw::dialog::DialogPresentationModifierAlt;
    if(key==Key::Tab) {
        m_open_combo=-1;m_scroll_drag=-1;
        for(int n=0;n<5;++n) {
            m_focus=(m_focus+(shift?4:1))%5;
            if((m_focus==2 && m_data.empty()) || (m_focus==3 && !m_ok_enabled) ||
               (m_focus<2 && m_yadonames.empty()))continue;
            break;
        }
        if(m_focus==2 && m_row<0 && !m_data.empty())select_row(0,0);
        return;
    }
    if(key==Key::Enter){dialog_presentation_enter(modifiers);return;}
    if(m_open_combo>=0) {
        if(key==Key::Space || key==Key::F4 || (alt && (key==Key::Up || key==Key::Down))) {
            choose_combo(m_combo_cursor);return;
        }
        I next=m_combo_cursor;
        if(key==Key::Up)--next;else if(key==Key::Down)++next;
        else if(key==Key::Home)next=0;else if(key==Key::End)next=m_yadonames.size()-1;
        else if(key==Key::PageUp)next-=transfer_popup_rows;else if(key==Key::PageDown)next+=transfer_popup_rows;
        else return; // 確定した UTF-8 文字列は dialog_presentation_text で一度だけ検索する。
        m_combo_cursor=std::clamp<I>(next,0,m_yadonames.size()-1);
        m_combo_offset=std::clamp<I>(m_combo_offset,std::max<I>(0,m_combo_cursor-transfer_popup_rows+1),m_combo_cursor);
        return;
    }
    if(m_focus<2) {
        if(key==Key::Space || key==Key::F4 || (alt && (key==Key::Up || key==Key::Down))) {
            open_combo(m_focus);return;
        }
        if(m_yadonames.empty())return;
        I next=m_focus==0?m_from_index:m_to_index;
        if(key==Key::Up)--next;else if(key==Key::Down)++next;
        else if(key==Key::Home)next=0;else if(key==Key::End)next=m_yadonames.size()-1;
        else return;
        open_combo(m_focus);choose_combo(std::clamp<I>(next,0,m_yadonames.size()-1));return;
    }
    if(key==Key::Space && m_focus>=3){dialog_presentation_enter(modifiers);return;}
    if(m_focus!=2 || m_data.empty())return;
    const auto l=transfer_layout(*this);
    if(control && key==Key::A){m_selected.assign(m_data.size(),true);return;}
    if(key==Key::Space) {
        if(m_row>=0)dialog_presentation_action(::cw::dialog::DialogPresentationAction::Toggle,static_cast<int>(m_row));
        return;
    }
    if(key==Key::Left || key==Key::Right) {
        m_horizontal_offset=std::clamp<I>(m_horizontal_offset+(key==Key::Left?-24:24),0,l.max_x);return;
    }
    I next=m_row<0?0:m_row;
    if(key==Key::Up)--next;else if(key==Key::Down)++next;
    else if(key==Key::Home)next=0;else if(key==Key::End)next=m_data.size()-1;
    else if(key==Key::PageUp)next-=l.rows;else if(key==Key::PageDown)next+=l.rows;else return;
    next=std::clamp<I>(next,0,m_data.size()-1);
    if(control && !shift) {
        m_row=next;
        m_scroll_offset=std::clamp<I>(m_scroll_offset,std::max<I>(0,next-l.rows+1),next);
    } else select_row(next,modifiers);
}
void TransferYadoDataDialog::dialog_presentation_scroll(float x,float y,int lines)
{
    if(!visible || m_transfer_running || !lines)return;
    const auto l=transfer_layout(*this);
    const double scale=std::max(1.0,::cw::g_UP_WIN),px=x/scale,py=y/scale;
    if(m_open_combo>=0) {
        m_combo_offset=std::clamp<I>(m_combo_offset+lines,0,std::max<I>(0,static_cast<I>(m_yadonames.size())-transfer_popup_rows));
    } else if(transfer_contains(l.list,px,py)) {
        if(m_modifiers & ::cw::dialog::DialogPresentationModifierShift)
            m_horizontal_offset=std::clamp<I>(m_horizontal_offset+lines*16,0,l.max_x);
        else m_scroll_offset=std::clamp<I>(m_scroll_offset+lines,0,l.max_y);
    } else for(int n=0;n<2;++n)if(transfer_contains(l.choices[n],px,py) && !m_yadonames.empty()) {
        const I selected=n==0?m_from_index:m_to_index;
        open_combo(n);choose_combo(std::clamp<I>(selected+(lines<0?-1:1),0,m_yadonames.size()-1));break;
    }
}
void TransferYadoDataDialog::dialog_presentation_pointer(::cw::dialog::DialogPresentationAction action,int index,
                                                        float x,float y,bool pressed)
{
    using Action=::cw::dialog::DialogPresentationAction;
    if(action!=Action::Auxiliary || index<1 || index>3) {
        ::cw::dialog::DialogPresentationProvider::dialog_presentation_pointer(action,index,x,y,pressed);return;
    }
    if(!pressed || !visible || m_transfer_running){m_scroll_drag=-1;return;}
    const auto l=transfer_layout(*this);
    if((index==3)!=(m_open_combo>=0))return;
    const bool horizontal=index==2;
    const auto track=index==1?l.vertical:index==2?l.horizontal:l.popup_track;
    I& value=index==1?m_scroll_offset:index==2?m_horizontal_offset:m_combo_offset;
    const I maximum=index==1?l.max_y:index==2?l.max_x:std::max<I>(0,static_cast<I>(m_yadonames.size())-transfer_popup_rows);
    const I page=index==1?l.rows:index==2?l.viewport.width:transfer_popup_rows;
    if(maximum<=0 || track.width<=0 || track.height<=0)return;
    const auto thumb=transfer_thumb(track,value,maximum,page,horizontal);
    const double coordinate=(horizontal?x:y)/std::max(1.0,::cw::g_UP_WIN);
    const I start=horizontal?track.x:track.y,length=horizontal?track.width:track.height;
    const I thumb_start=horizontal?thumb.x:thumb.y,thumb_length=horizontal?thumb.width:thumb.height;
    if(m_scroll_drag!=index) {
        m_scroll_drag=index;
        if(coordinate<thumb_start || coordinate>=thumb_start+thumb_length) {
            value=std::clamp<I>(value+(coordinate<thumb_start?-page:page),0,maximum);
            const auto next=transfer_thumb(track,value,maximum,page,horizontal);
            m_scroll_drag_offset=std::clamp(coordinate-(horizontal?next.x:next.y),0.0,static_cast<double>(thumb_length));
            request_dialog_presentation_refresh();return;
        }
        m_scroll_drag_offset=coordinate-thumb_start;
    }
    const auto ratio=std::clamp((coordinate-start-m_scroll_drag_offset)/std::max<I>(1,length-thumb_length),0.0,1.0);
    value=static_cast<I>(ratio*maximum+0.5);
    request_dialog_presentation_refresh();
}
void TransferYadoDataDialog::dialog_presentation_pointer_cancel()
{
    m_scroll_drag=-1;m_modifiers=0;
}

bool TransferYadoDataDialog::dialog_presentation_finished() const noexcept
{
    return !visible;
}

void TransferYadoDataDialog::dialog_presentation_complete()
{
    m_open_combo=-1;m_scroll_drag=-1;m_modifiers=0;
    if(visible) {
        m_cancelled=true;m_modal_result=0;visible=false;
        if(m_thread) m_thread->m_cancel_requested.store(true,std::memory_order_release);
    }
    ::cw::dialog::clear_transient_dialog_presentation(this);
}

void _TransferThread::initialize(std::shared_ptr<::cw::dialog::transfer::TransferYadoDataDialog> arg_outer, ::cw::lib::String arg_fromyado, ::cw::lib::String arg_toyado, std::vector<TransferItem> arg_seq)
{
    m_outer = arg_outer;
    m_fromyado = std::move(arg_fromyado);
    m_toyado = std::move(arg_toyado);
    m_seq = std::move(arg_seq);
    const auto from_environment_path = generic(fs::u8path(m_fromyado) / "Environment.xml");
    m_fromscedir = "Scenario";
    if (const auto from_environment = ::cw::data::xml2etree(from_environment_path, "", std::nullopt, std::nullopt, true); from_environment) {
        m_fromscedir = skin_to_scenario(from_environment->gettext("Property/Skin", ""));
    }
    const auto destination_environment_path = generic(fs::u8path(m_toyado) / "Environment.xml");
    m_environment = ::cw::data::xml2etree(destination_environment_path, "", std::nullopt, std::nullopt, true);
    if (!m_environment) throw std::runtime_error("transfer destination Environment.xml is missing");
    m_toscedir = skin_to_scenario(m_environment->gettext("Property/Skin", ""));
    m_imgpaths.clear();
    m_membertable.clear();
    m_saved_variables = ::cw::data::YadoData::get_savedvariables(m_environment);
    m_skin_vars.reset();
    const auto skin_variables_path = (fs::u8path(m_toyado) / "SkinVariables.xml");
    if (fs::is_regular_file(skin_variables_path)) {
        if (const auto tree = ::cw::data::xml2etree(generic(skin_variables_path), "", std::nullopt, std::nullopt, true); tree && tree->getroot()) {
            m_skin_vars = SkinVariables{tree, ::cw::data::YadoData::get_savedvariables_with_skin(tree->getroot())};
        }
    }
    {
        std::lock_guard guard(m_progress_mutex);
        m_num = 0;
        m_msg.clear();
        m_finished = false;
        m_cancelled = false;
        m_failed = false;
        m_error.clear();
    }
    m_cancel_requested.store(false,std::memory_order_release);
}

void _TransferThread::run()
{
    auto outer = m_outer.lock();
    if (!outer) {
        mark_failed("転送ダイアログが破棄されました");
        return;
    }
    std::shared_ptr<::cw::yadodb::YadoDB> yadodb;
    try {
        if (::cw::g_fsync) ::cw::g_fsync->sync();
        yadodb = std::make_shared<::cw::yadodb::YadoDB>();
        yadodb->initialize(m_toyado, ::cw::yadodb::g_YADO);
        // XML更新とDB更新は、YadoDBのcommit/close境界に合わせて確定する。
        auto saved_jpdcimage = yadodb->get_savedjpdcimage();
        auto self = std::shared_ptr<_TransferThread>(this, [](const auto*) {});
        std::vector<std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>>> delayed_partyrecords;
        for (const auto& item : m_seq) {
            if (m_cancel_requested.load(std::memory_order_acquire)) {
                mark_cancelled();
                yadodb->close();
                return;
            }
            const auto kind = transfer_item_kind(item);
            if (kind == TransferItemKind::partyrecord) {
                delayed_partyrecords.push_back(
                    std::get<std::vector<std::shared_ptr<::cw::header::PartyRecordHeader>>>(item));
                continue;
            }
            set_progress_message(format_transfer_message(
                transfer_message("transfer_processing", "%sを転送中..."),
                {transfer_item_label(item)}));
            switch (kind) {
            case TransferItemKind::partyrecord:
                continue;
            case TransferItemKind::element: {
                const auto element = std::get<std::shared_ptr<::cw::data::CWPyElement>>(item);
                if (!element) throw std::invalid_argument("TransferItem contains a null XML element");
                if (element->m_tag == "Bookmarks") {
                    outer->transfer_bookmark(m_fromscedir, m_toscedir, m_fromyado, m_toyado, element, self);
                } else if (element->m_tag == "Gossips") {
                    outer->transfer_gossip(m_fromyado, m_toyado, element, self);
                } else if (element->m_tag == "CompleteStamps") {
                    outer->transfer_completestamp(m_fromyado, m_toyado, element, self);
                } else {
                    throw std::invalid_argument("unknown transfer XML tag: " + element->m_tag);
                }
                break;
            }
            case TransferItemKind::saved_variables:
                outer->transfer_savedvariables(m_fromyado, m_toyado, nullptr,
                                               std::get<SavedVariableTransfer>(item), self);
                break;
            case TransferItemKind::skin_variables:
                outer->transfer_skinvariables(m_fromyado, m_toyado, nullptr,
                                              std::get<SkinVariableTransfer>(item), self);
                break;
            case TransferItemKind::cash:
                if (!m_environment) throw std::runtime_error("destination Environment.xml is missing");
                // ネイティブ版の所持金転送は、意図的に九桁の残高上限を維持する。 Python
                // は同じ転送結果を 9,999,999 で制限する点が異なる。
                m_environment->edit("Property/Cashbox", std::to_string(::cw::lib::money::add(m_environment->getint("Property/Cashbox", std::nullopt, 0), std::get<I>(item))), std::nullopt);
                m_environment->m_is_edited = true;
                increment_progress();
                break;
            case TransferItemKind::album: {
                const auto album = std::get<std::vector<std::shared_ptr<::cw::header::AdventurerHeader>>>(item);
                outer->transfer_album(m_fromyado, m_toyado, album, yadodb, self);
                break;
            }
            case TransferItemKind::party:
                outer->transfer_party(m_fromyado, m_toyado, std::get<std::shared_ptr<::cw::header::PartyHeader>>(item), yadodb, self);
                break;
            case TransferItemKind::adventurer: {
                const auto header = std::get<std::shared_ptr<::cw::header::AdventurerHeader>>(item);
                if (!header) throw std::invalid_argument("TransferItem contains a null adventurer header");
                const auto path = value_string(header->m_fpath);
                auto data = ::cw::data::xml2etree(path, "", std::nullopt, std::nullopt, true);
                outer->transfer_adventurer(m_fromyado, m_toyado, data, yadodb, self, false);
                break;
            }
            case TransferItemKind::card: {
                const auto header = std::get<std::shared_ptr<::cw::header::CardHeader>>(item);
                if (!header) throw std::invalid_argument("TransferItem contains a null card header");
                const auto path = header->m_fpath;
                auto data = ::cw::data::xml2etree(path, "", std::nullopt, std::nullopt, true);
                outer->transfer_card(m_fromyado, m_toyado, data, yadodb, self);
                break;
            }
            case TransferItemKind::saved_jpdc_image:
                outer->transfer_savedjpdcimage(m_fromyado, m_toyado, std::get<std::shared_ptr<::cw::header::SavedJPDCImageHeader>>(item), yadodb, saved_jpdcimage, self);
                break;
            }
        }
        if (!delayed_partyrecords.empty()) {
            for (const auto& records : delayed_partyrecords) {
                if (m_cancel_requested.load(std::memory_order_acquire)) {
                    mark_cancelled();
                    yadodb->close();
                    return;
                }
                set_progress_message(format_transfer_message(
                    transfer_message("transfer_processing", "%sを転送中..."),
                    {transfer_item_label(TransferItem{records})}));
                outer->transfer_partyrecord(m_fromyado, m_toyado, records, yadodb, self);
            }
        }
        // YadoDB は実際の SQLite 接続を所有する。 予約済み XML の書き
        // 込み完了と接続終了より前に、Commit で転送したデータベース行を保存する。
        yadodb->commit();
        if (m_environment && m_environment->m_is_edited) m_environment->write_xml(true);
        if (m_skin_vars && std::get<0>(*m_skin_vars) && std::get<0>(*m_skin_vars)->m_is_edited) std::get<0>(*m_skin_vars)->write_xml(true);
        // write_xml は Python と同様、FileSync
        // を通して XML を書き込む。 出力先への書き込みが保存される
        // まで転送完了を通知しない。 先に通知すると、直後の再読み込みで
        // 古い宿が見え、遅れた書き込みが次の操作と競合する可能性がある。
        if (::cw::g_fsync) ::cw::g_fsync->sync();
        yadodb->close();
        mark_finished();
    } catch (const std::exception& error) {
        if (yadodb) yadodb->close();
        mark_failed(error.what());
    } catch (...) {
        if (yadodb) yadodb->close();
        mark_failed("不明な転送例外");
    }
}

void _TransferThread::set_progress_message(::cw::lib::String arg_message)
{
    {std::lock_guard guard(m_progress_mutex);m_msg=std::move(arg_message);}
    publish_progress();
}

void _TransferThread::increment_progress()
{
    {std::lock_guard guard(m_progress_mutex);++m_num;}
    publish_progress();
}

void _TransferThread::publish_progress()
{
    const auto state=progress_snapshot();
    if(m_progress_callback) m_progress_callback(state.num,state.msg);
}

void _TransferThread::mark_finished()
{
    std::lock_guard guard(m_progress_mutex);
    m_finished = true;
}

void _TransferThread::mark_cancelled()
{
    std::lock_guard guard(m_progress_mutex);
    m_cancelled = true;
    m_finished = true;
}

void _TransferThread::mark_failed(::cw::lib::String arg_error)
{
    std::lock_guard guard(m_progress_mutex);
    m_failed = true;
    m_finished = true;
    m_error = std::move(arg_error);
    m_msg = m_error;
}

_TransferThread::ProgressSnapshot _TransferThread::progress_snapshot() const
{
    std::lock_guard guard(m_progress_mutex);
    return {m_num, m_msg, m_finished, m_cancelled, m_failed, m_error};
}

::cw::lib::Value g__TransferType{};

::cw::lib::String _TransferThread___init____skindir_to_scedir(::cw::lib::String arg_skindir)
{
    return skin_to_scenario(arg_skindir);
}

